const FONT = "Times New Roman";
const SIZE = 28; // 14 pt
const LINE = 360; // exactly 18 pt
const INDENT = 709; // 1.25 cm

const run = (text, opts = {}) => new TextRun({ text, font: FONT, size: SIZE, ...opts });
const P = (children, opts = {}) =>
  new Paragraph({
    alignment: AlignmentType.JUSTIFIED,
    spacing: { line: LINE, lineRule: "exact", before: 0, after: 0 },
    indent: { firstLine: INDENT },
    children: typeof children === "string" ? [run(children)] : children,
    ...opts,
  });
const text = (s) => P(s);
const rich = (parts) => P(parts.map((p) => (typeof p === "string" ? run(p) : run(p.t, p))));
const empty = () => new Paragraph({ spacing: { line: LINE, lineRule: "exact" }, children: [run("")] });
const H1 = (s) =>
  new Paragraph({
    heading: HeadingLevel.HEADING_1,
    alignment: AlignmentType.LEFT,
    indent: { firstLine: INDENT },
    spacing: { line: LINE, lineRule: "exact", before: 240, after: 240 },
    children: [run(s, { bold: true })],
  });
const H1Center = (s) =>
  new Paragraph({
    heading: HeadingLevel.HEADING_1,
    alignment: AlignmentType.CENTER,
    spacing: { line: LINE, lineRule: "exact", before: 0, after: 240 },
    children: [run(s, { bold: true })],
  });
const H2 = (s) =>
  new Paragraph({
    heading: HeadingLevel.HEADING_2,
    alignment: AlignmentType.LEFT,
    indent: { firstLine: INDENT },
    spacing: { line: LINE, lineRule: "exact", before: 200, after: 120 },
    children: [run(s, { bold: true })],
  });
const bullets = (items) =>
  items.map(
    (s) =>
      new Paragraph({
        numbering: { reference: "dash", level: 0 },
        alignment: AlignmentType.JUSTIFIED,
        spacing: { line: LINE, lineRule: "exact" },
        children: typeof s === "string" ? [run(s)] : s.map((p) => (typeof p === "string" ? run(p) : run(p.t, p))),
      }),
  );
const figure = (file, caption, widthCm) => {
  const buf = fs.readFileSync(file);
  const { width, height } = pngSize(buf);
  const w = Math.round(widthCm * 37.8);
  const h = Math.round((height / width) * w);
  return [
    new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { line: 240, lineRule: "auto", before: 120, after: 60 },
      keepNext: true,
      children: [new ImageRun({ type: "png", data: buf, transformation: { width: w, height: h } })],
    }),
    new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { line: LINE, lineRule: "exact", before: 0, after: 200 },
      children: [run(caption)],
    }),
  ];
};
function pngSize(buf) {
  return { width: buf.readUInt32BE(16), height: buf.readUInt32BE(20) };
}
const cellText = (s, opts = {}) =>
  new Paragraph({
    alignment: opts.align ?? AlignmentType.CENTER,
    spacing: { line: 276, lineRule: "auto", before: 20, after: 20 },
    children: [run(String(s), { size: 24, bold: opts.bold ?? false })],
  });
const border = { style: BorderStyle.SINGLE, size: 4, color: "000000" };
const borders = { top: border, bottom: border, left: border, right: border };
function table(widthsCm, header, rows, opts = {}) {
  const widths = widthsCm.map((c) => Math.round(c * 567));
  const total = widths.reduce((a, b) => a + b, 0);
  const mk = (cells, isHeader) =>
    new TableRow({
      tableHeader: isHeader,
      children: cells.map(
        (c, i) =>
          new TableCell({
            borders,
            width: { size: widths[i], type: WidthType.DXA },
            verticalAlign: VerticalAlign.CENTER,
            shading: isHeader ? { type: ShadingType.CLEAR, fill: "EDEDED", color: "auto" } : undefined,
            children: [cellText(c, { bold: isHeader || (opts.boldFirst && i === 0), align: i === 0 && !isHeader ? AlignmentType.LEFT : AlignmentType.CENTER })],
          }),
      ),
    });
  return new Table({
    width: { size: total, type: WidthType.DXA },
    columnWidths: widths,
    rows: [mk(header, true), ...rows.map((r) => mk(r, false))],
  });
}
const tableCaption = (s) =>
  new Paragraph({
    alignment: AlignmentType.LEFT,
    spacing: { line: LINE, lineRule: "exact", before: 200, after: 60 },
    keepNext: true,
    children: [run(s)],
  });
const afterTable = () => new Paragraph({ spacing: { line: 200, lineRule: "exact", before: 0, after: 120 }, children: [run("", { size: 8 })] });

// math helpers
const m = (s) => new MathRun(s);
const sub = (b, s) => new MathSubScript({ children: [m(b)], subScript: [m(s)] });
const sup = (b, s) => new MathSuperScript({ children: [m(b)], superScript: [m(s)] });
const frac = (n, d) => new MathFraction({ numerator: n, denominator: d });
const formula = (file, number, heightCm) => {
  const buf = fs.readFileSync(file);
  const { width, height } = pngSize(buf);
  const h = Math.round(heightCm * 37.8);
  const w = Math.round((width / height) * h);
  const none = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
  const noBorders = { top: none, bottom: none, left: none, right: none };
  return new Table({
    width: { size: 9354, type: WidthType.DXA },
    columnWidths: [8300, 1054],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            borders: noBorders,
            width: { size: 8300, type: WidthType.DXA },
            verticalAlign: VerticalAlign.CENTER,
            children: [new Paragraph({ alignment: AlignmentType.CENTER, spacing: { line: 240, lineRule: "auto", before: 80, after: 80 }, children: [new ImageRun({ type: "png", data: buf, transformation: { width: w, height: h } })] })],
          }),
          new TableCell({
            borders: noBorders,
            width: { size: 1054, type: WidthType.DXA },
            verticalAlign: VerticalAlign.CENTER,
            children: [new Paragraph({ alignment: AlignmentType.RIGHT, spacing: { line: 240, lineRule: "auto" }, children: [run(`(${number})`)] })],
          }),
        ],
      }),
    ],
  });
};

